import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';

function ProfilePage() {
    const navigate = useNavigate();
    const [user, setUser] = useState(null);

    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            setUser(JSON.parse(storedUser));
        }
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/auth');
    };

    return (
        <Layout>
            <div className="p-4 md:p-6 w-full">
                <div className="flex justify-between items-end border-b border-glass-stroke pb-4 mb-8">
                    <div>
                        <h1 className="text-headline-lg-mobile md:text-headline-lg font-inter text-on-surface">
                            Profile
                        </h1>
                        <p className="text-body-md font-inter text-on-surface-variant mt-1">
                            Manage your account details and preferences.
                        </p>
                    </div>
                </div>

                <div className="max-w-2xl">
                    <div className="glass-card p-4 md:p-card-padding">
                        <div className="flex flex-col sm:flex-row items-center sm:items-start gap-6 mb-8 text-center sm:text-left">
                            <div className="w-24 h-24 rounded-2xl bg-gradient-to-br from-sky-blue to-deep-sky-blue flex items-center justify-center text-4xl shadow-lg border border-white/10 shrink-0">
                                <span className="material-symbols-outlined text-[48px] text-white">person</span>
                            </div>
                            <div className="flex-1 mt-2 sm:mt-0">
                                <h2 className="text-headline-lg text-on-surface">{user?.name || 'User'}</h2>
                                <p className="text-on-surface-variant text-body-md mt-1 break-all">{user?.email || 'user@example.com'}</p>
                                <span className="inline-block mt-3 px-3 py-1 rounded-full text-label-caps uppercase tracking-widest bg-deep-sky-blue/20 text-deep-sky-blue border border-deep-sky-blue/30">
                                    Admin Access
                                </span>
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div>
                                <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                    Full Name
                                </label>
                                <input
                                    type="text"
                                    value={user?.name || ''}
                                    readOnly
                                    className="glass-input opacity-70 cursor-not-allowed w-full"
                                />
                            </div>

                            <div>
                                <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                    Email Address
                                </label>
                                <input
                                    type="email"
                                    value={user?.email || ''}
                                    readOnly
                                    className="glass-input opacity-70 cursor-not-allowed w-full"
                                />
                            </div>

                            <div className="pt-6 border-t border-glass-stroke flex flex-col sm:flex-row justify-between items-center gap-4 text-center sm:text-left">
                                <p className="text-on-surface-variant text-[13px]">
                                    To update your details, please contact support.
                                </p>
                                <button
                                    onClick={handleLogout}
                                    className="btn-ghost flex items-center gap-2 text-error-red hover:bg-error/10 hover:border-error/30 w-full sm:w-auto justify-center"
                                >
                                    <span className="material-symbols-outlined text-[18px]">logout</span>
                                    Logout
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </Layout>
    );
}

export default ProfilePage;
